                if not ser.in_waiting:
                    print("Device not present or not responding. Exiting...")
                    return
                data = ser.readline().decode('utf-8').strip()
                if not data:
                    print("Received empty data. Exiting...")
                    return
                print(f"Received: {data}")
                time.sleep(2)  # Wait for 2 seconds before the next read

    except serial.SerialException as e:
        print(f"Error reading from device: {e}")
        return

def main():
    read_thread = threading.Thread(target=read_from_device)
    read_thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
        read_thread.join()  # Ensure the read thread has finished before exiting
        ser.close()  # Close the serial port

